algorithms.pseudocode:
INPUT  bars B[0..n-1], centres c[0..n-1], bin width w
OUTPUT amplitude, vertex, and a certification status

j  <- argmax over interior indices 1..n-2 of B[i]
ym <- B[j-1];  y0 <- B[j];  yp <- B[j+1]
D  <- ym - 2*y0 + yp            # discrete curvature
A  <- ym - yp                   # neighbour asymmetry

if D >= 0:
    return {vertex: c[j], source: 'argmax bin centre',
            status: 'degenerate: fit not strictly concave'}

amplitude <- y0 - (yp - ym)^2 / (8*D)     # always >= y0

if |A| > -D:
    return {amplitude, vertex: c[j], source: 'argmax bin centre',
            status: 'degenerate: |A| > |D|, apex not certifiable'}

return {amplitude, vertex: c[j] + w*A/(2*D), source: 'quadratic fit',
        status: 'certified: |vertex - c[j]| <= w/2'}

INPUT  f; W: bin counts; S: shifts; window [lo, hi]
OUTPUT per-cell concave fractions and their aggregate

for n_bins in W:
    w <- 1 / n_bins
    for sh in S:
        o <- sh * w
        B[i] <- (1/w) * INTEGRATE(f, o + i*w, o + i*w + w)  for all i
        for k in 1 .. n_bins-2:
            D2[k] <- B[k+1] - 2*B[k] + B[k-1]
        inside <- { k : lo <= o + (k + 1/2)*w <= hi }
        if inside is empty: continue
        frac <- |{ k in inside : D2[k] < 0 }| / |inside|
        emit (n_bins, sh) -> {concave_fraction: frac,
                              min_second_difference: min D2 over inside}

RETURN min, mean of concave_fraction over cells
       (a concave feature gives 1 in every cell, by the sign certificate)
